src = r'''
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda_fp16.h>
#include <cuda_runtime.h>

#define THREADS 256

__global__ void layernorm_forward_reduce(
    const half* __restrict__ input,
    float* __restrict__ mean,
    float* __restrict__ var,
    int N, int C, int H, int W)
{
    const int n = blockIdx.x;
    const int tid = threadIdx.x;
    const int total = C * H * W;
    const int base = n * total;

    // ---- mean ----
    float sum = 0.f;
    for (int i = tid; i < total; i += blockDim.x) {
        sum += __half2float(input[base + i]);
    }
    __shared__ float shm[THREADS];
    shm[tid] = sum;
    __syncthreads();
    for (int stride = blockDim.x / 2; stride > 0; stride >>= 1) {
        if (tid < stride) shm[tid] += shm[tid + stride];
        __syncthreads();
    }
    float batch_mean = shm[0] / total;

    // ---- variance ----
    float sum_sq = 0.f;
    for (int i = tid; i < total; i += blockDim.x) {
        float v = __half2float(input[base + i]) - batch_mean;
        sum_sq += v * v;
    }
    shm[tid] = sum_sq;
    __syncthreads();
    for (int stride = blockDim.x / 2; stride > 0; stride >>= 1) {
        if (tid < stride) shm[tid] += shm[tid + stride];
        __syncthreads();
    }
    float batch_var = shm[0] / total;

    if (tid == 0) {
        mean[n] = batch_mean;
        var[n] = batch_var;
    }
}

__global__ void layernorm_forward_apply(
    const half* __restrict__ input,
    half* __restrict__ output,
    const float* __restrict__ mean,
    const float* __restrict__ var,
    const half* __restrict__ weight,
    const half* __restrict__ bias,
    int N, int C, int H, int W,
    float eps)
{
    const int idx = blockIdx.x * blockDim.x + threadIdx.x;
    const int total = N * C * H * W;
    if (idx >= total) return;

    const int inner = idx % (C * H * W);
    const int n = idx / (C * H * W);

    float m = mean[n];
    float v = var[n];
    float inv_std = rsqrtf(v + eps);

    float x = __half2float(input[idx]);
    float y = (x - m) * inv_std;

    float w = __half2float(weight[inner]);
    float b = __half2float(bias[inner]);

    y = y * w + b;
    output[idx] = __float2half(y);
}

torch::Tensor layernorm_forward(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    float eps)
