        reinterpret_cast<half*>(input.data_ptr()),
        mean.data_ptr<float>(),
        var.data_ptr<float>(),
        N, C, H, W);

    const int total = N * C * H * W;
    const dim3 blocks_apply((total + THREADS - 1) / THREADS);
    layernorm_forward_apply<<<blocks_apply, threads, 0,
